CREATE TABLE IF NOT EXISTS requisition (
    tenant_id                tenant_ref   NOT NULL REFERENCES tenant (tenant_id),
    requisition_id           uuid         NOT NULL,
    requisition_key          semantic_key NOT NULL,
    position_ref             text NOT NULL,
    hiring_manager_ref       text NOT NULL,
    openings                 integer NOT NULL DEFAULT 1,
    status                   text NOT NULL DEFAULT 'DRAFT',
    effective_from           date         NOT NULL,
    known_at                 timestamptz  NOT NULL,
    recorded_at              timestamptz  NOT NULL DEFAULT now(),

    PRIMARY KEY (tenant_id, requisition_id),
    CONSTRAINT requisition_key_unique UNIQUE (tenant_id, requisition_key),
    CONSTRAINT requisition_openings_check CHECK (openings > 0),
    CONSTRAINT requisition_status_check CHECK (status IN ('DRAFT', 'APPROVED', 'PUBLISHED', 'FILLED', 'CLOSED')),
    CONSTRAINT requisition_knowledge_order CHECK (known_at <= recorded_at)
);

CREATE INDEX IF NOT EXISTS requisition_recorded
    ON requisition (tenant_id, recorded_at DESC);

ALTER TABLE requisition ENABLE ROW LEVEL SECURITY;
ALTER TABLE requisition FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON requisition
    USING (tenant_id = NULLIF(current_setting('app.tenant_id', true), '')::uuid)
    WITH CHECK (tenant_id = NULLIF(current_setting('app.tenant_id', true), '')::uuid);
GRANT SELECT, INSERT, UPDATE ON requisition TO hcmnext_app;

CREATE TABLE IF NOT EXISTS requisition_revision (
    tenant_id                tenant_ref   NOT NULL REFERENCES tenant (tenant_id),
    revision_id              uuid         NOT NULL,
    requisition_id           uuid         NOT NULL,
    revision_sequence        bigint       NOT NULL,
    approved_openings        integer NOT NULL,
    approved_fte             numeric(6,4) NOT NULL,
    approval_digest          text NOT NULL,
    known_at                 timestamptz  NOT NULL,
    recorded_at              timestamptz  NOT NULL DEFAULT now(),

    PRIMARY KEY (tenant_id, revision_id),
    CONSTRAINT requisition_revision_revision_positive CHECK (revision_sequence >= 1),
    CONSTRAINT requisition_revision_approved_openings_check CHECK (approved_openings > 0),
    CONSTRAINT requisition_revision_approved_fte_check CHECK (approved_fte > 0),
    CONSTRAINT requisition_revision_knowledge_order CHECK (known_at <= recorded_at),
    FOREIGN KEY (tenant_id, requisition_id) REFERENCES requisition (tenant_id, requisition_id)
);

CREATE INDEX IF NOT EXISTS requisition_revision_recorded
    ON requisition_revision (tenant_id, recorded_at DESC);

CREATE OR REPLACE TRIGGER requisition_revision_append_only
    BEFORE UPDATE OR DELETE ON requisition_revision
    FOR EACH ROW EXECUTE FUNCTION forbid_mutation();

REVOKE UPDATE, DELETE ON requisition_revision FROM PUBLIC;

ALTER TABLE requisition_revision ENABLE ROW LEVEL SECURITY;
ALTER TABLE requisition_revision FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON requisition_revision
    USING (tenant_id = NULLIF(current_setting('app.tenant_id', true), '')::uuid)
    WITH CHECK (tenant_id = NULLIF(current_setting('app.tenant_id', true), '')::uuid);
GRANT SELECT, INSERT ON requisition_revision TO hcmnext_app;

